// KiMapka 0.105 — one workspace, precise cells, direct manipulation and projected 3D.
let activeElement=null,activeField=null,sceneYaw=-.65,sceneTilt=.62,sceneScope='room',sceneCutaway=true;
const isOpening=e=>['door','window','vent','obstacle'].includes(e.type);
const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
const measureLabel={x:'Od lewej',y:'Od podłogi',w:'Szerokość',h:'Wysokość',d:'Głębokość'};
function fits(r,e){return e.x>=0&&e.y>=0&&e.x+(isOpening(e)?e.w:0)<=length(r,e.wall)&&e.y+(isOpening(e)?e.h:0)<=r.h}
function cell(r,e,key){const id=e?`cell-${e.id}-${key}`:`cell-room-${key}`,v=e?e[key]:r[key];return `<div class="measurement-cell"><input id="${id}" aria-label="${e?types[e.type][0]:r.name}: ${measureLabel[key]}" type="number" inputmode="numeric" min="${['w','h','d'].includes(key)?1:0}" max="100000" step="1" value="${v}" onfocus="focusMeasure('${e?.id||''}','${key}')" oninput="editMeasure(this,'${e?.id||''}','${key}')" onblur="finishMeasure(this,'${e?.id||''}','${key}')" onkeydown="if(event.key==='Enter'){this.blur()}else if(event.key==='Escape'){this.value=${v};this.dispatchEvent(new Event('input'));this.blur()}"><button title="Zdjęcie dla: ${measureLabel[key]}" aria-label="Zdjęcie dla: ${e?types[e.type][0]:r.name}, ${measureLabel[key]}" onclick="openInlinePhoto('${id}','${e?.id||''}')">📷</button></div>`}
function renderEditor(){const r=room(),elems=r.elements.filter(e=>e.wall===wall);if(!elems.some(e=>e.id===activeElement))activeElement=null;$('#content').innerHTML=`<div class="editor-heading"><div><div class="eyebrow">POMIESZCZENIE ${String(data.rooms.indexOf(r)+1).padStart(2,'0')} / EDYCJA NA ŻYWO</div><input class="room-title" aria-label="Nazwa pokoju" value="${esc(r.name)}" maxlength="60" onchange="room().name=this.value.trim()||'Pokój';save();render()"></div><span class="area-chip" id="roomArea">${(r.w*r.d/1e6).toFixed(2)} m²</span></div><div class="room-measures">${[['w','A / C · szerokość'],['d','B / D · głębokość'],['h','Wysokość pokoju']].map(([k,t])=>`<div><label for="cell-room-${k}">${t} <span>mm</span></label>${cell(r,null,k)}</div>`).join('')}</div><div class="editor-stage"><div class="card wall-card"><div class="card-top"><h3>Ściana ${'ABCD'[wall]}</h3><div class="wall-tabs">${[0,1,2,3].map(w=>`<button class="${wall===w?'active':''}" onclick="wall=${w};activeField=null;render()">${'ABCD'[w]}</button>`).join('')}</div></div><div class="drawing" id="wallCanvas">${wallSVG(r,wall)}</div><div class="drawing-bottom"><span>Chwyć element i przesuń · krok 1 mm</span><span id="dragReadout">${length(r,wall)} × ${r.h} mm</span></div></div><div class="card model-card"><div class="card-top"><h3>Podgląd 3D</h3><button class="tiny" onclick="open3D()">⤢ Powiększ</button></div><button class="model-mini" id="mini3D" onclick="open3D()" aria-label="Powiększ dynamiczny podgląd 3D"></button><div class="model-caption">Ściany, otwory i instalacje · na żywo</div></div></div><div class="add-strip">${Object.entries(types).map(([k,t])=>`<button onclick="addInline('${k}')"><b>${t[1]}</b> ${t[0]}</button>`).join('')}</div><div class="card table-card"><div class="card-top"><h3>Wymiary i położenie · ściana ${'ABCD'[wall]}</h3><span class="muted">mm · zapis automatyczny</span></div><div class="measure-scroll"><table class="measure-table"><thead><tr><th>Element</th><th>X · od lewej</th><th>Y · od podłogi</th><th>Szerokość</th><th>Wysokość</th><th>Opis</th><th></th></tr></thead><tbody>${elems.map((e,i)=>`<tr data-row="${e.id}" class="${activeElement===e.id?'selected':''}"><td><button class="row-select" onclick="selectInline('${e.id}')"><span>${types[e.type][1]}</span>${types[e.type][0]} ${i+1}</button><small>${isOpening(e)?'lewa / dolna krawędź':'środek / oś'}</small></td><td>${cell(r,e,'x')}</td><td>${cell(r,e,'y')}</td><td>${isOpening(e)?cell(r,e,'w'):'<span class="dash">—</span>'}</td><td>${isOpening(e)?cell(r,e,'h'):'<span class="dash">—</span>'}</td><td><input class="note-cell" aria-label="Opis ${types[e.type][0]} ${i+1}" value="${esc(e.note)}" maxlength="250" placeholder="Rodzaj, uwagi…" onchange="room().elements.find(e=>e.id==='${e.id}').note=this.value;save()"></td><td><button class="delete-inline" aria-label="Usuń ${types[e.type][0]} ${i+1}" onclick="deleteInline('${e.id}')">×</button></td></tr>`).join('')}</tbody></table>${!elems.length?'<div class="empty">Dodaj element przyciskiem powyżej. Jego wymiary pojawią się w komórkach.</div>':''}</div></div><div id="editNotice" class="edit-notice" role="status">Dotknij komórki, żeby wpisać wymiar. Rysunki 2D i 3D aktualizują się od razu.</div><section id="inlinePhoto" class="card" hidden><div class="card-top"><h3 id="photoHeading">Zdjęcie pomiaru</h3><button onclick="document.getElementById('inlinePhoto').hidden=true">Zwiń</button></div><div class="photo-body"><input id="photoInput" type="file" accept="image/*"><img id="photoPreview" class="photo-preview" hidden><div id="ocrPanel"></div><p class="muted">OCR eksperymentalny. Sprawdź wynik i jednostkę przed zatwierdzeniem.</p></div></section>`;bindWallDrag();update3D();}
function editMeasure(input,id,key){const r=room(),obj=id?r.elements.find(e=>e.id===id):r;const n=Number(input.value);if(input.value===''||!Number.isInteger(n)||n<(['w','h','d'].includes(key)?1:0)||n>100000){input.classList.add('invalid');$('#editNotice').textContent='Wpisz pełny wymiar w mm w zakresie 0–100000 (wymiary większe od zera).';return}const trial={...obj,[key]:n};if(id?!fits(r,trial):r.elements.some(e=>!fits(trial,e))){input.classList.add('invalid');$('#editNotice').textContent=id?'Element wychodzi poza ścianę. Popraw wymiar.':'Ten wymiar pozostawiłby element poza ścianą. Najpierw zmień położenie lub rozmiar elementu.';return}input.classList.remove('invalid');const changed=obj[key]!==n;obj[key]=n;if(!id&&changed)data.links=data.links.filter(l=>l.a!==r.id&&l.b!==r.id);save();$('#editNotice').textContent=!id&&changed?'Zapisano wymiar pokoju. Połączenia tego pokoju wymagają ponownego wskazania.':'Zapisano. Rysunek i model 3D są aktualne.';refreshGeometry();}
function finishMeasure(input,id,key){if(input.classList.contains('invalid')||input.value===''){input.value=(id?room().elements.find(e=>e.id===id):room())[key];input.classList.remove('invalid');$('#editNotice').textContent='Nieprawidłowy wymiar nie został zapisany — przywrócono ostatnią poprawną wartość.'}}
function focusMeasure(id,key){activeElement=id||null;activeField={id,key};document.querySelectorAll('[data-row]').forEach(row=>row.classList.toggle('selected',row.dataset.row===id));refreshWall();}
function selectInline(id){activeElement=id;activeField={id,key:'x'};document.querySelectorAll('[data-row]').forEach(row=>row.classList.toggle('selected',row.dataset.row===id));refreshWall();update3D();}
function refreshWall(){if(!$('#wallCanvas'))return;$('#wallCanvas').innerHTML=wallSVG(room(),wall);bindWallDrag();}
function refreshGeometry(){refreshWall();update3D();if($('#roomArea'))$('#roomArea').textContent=(room().w*room().d/1e6).toFixed(2)+' m²';if($('#dragReadout'))$('#dragReadout').textContent=activeElement?(()=>{const e=room().elements.find(e=>e.id===activeElement);return e?`X ${e.x} · Y ${e.y} mm`:''})():`${length(room(),wall)} × ${room().h} mm`;}
function addInline(type){const r=room(),L=length(r,wall),opening=isOpening({type}),w=Math.min(type==='window'?1200:type==='door'?900:150,L),h=Math.min(type==='window'?1400:type==='door'?2100:150,r.h),e={id:uid(),wall,type,x:Math.min(500,L-(opening?w:0)),y:type==='door'?0:Math.min(type==='window'?900:300,r.h-(opening?h:0)),w,h,note:'',photo:''};r.elements.push(e);activeElement=e.id;activeField={id:e.id,key:'x'};save();render();$('#cell-'+e.id+'-x')?.focus({preventScroll:true});}
let deletedElement=null;function deleteInline(id){const r=room(),i=r.elements.findIndex(e=>e.id===id);deletedElement={roomId:r.id,e:r.elements[i],i};r.elements.splice(i,1);activeElement=null;save();render();$('#editNotice').innerHTML='Element usunięty. <button class="tiny" onclick="undoDelete()">Cofnij</button>'}function undoDelete(){if(!deletedElement)return;const d=deletedElement,r=data.rooms.find(r=>r.id===d.roomId);if(r)r.elements.splice(d.i,0,d.e);deletedElement=null;save();render();}
// Keep existing PDF generation on the same geometry, without editor handles.
wallSVG=function(r,w){const L=length(r,w),s=Math.min(580/L,260/r.h),ox=(720-L*s)/2,oy=65,b=oy+r.h*s;const chosen=r.id===roomId?r.elements.find(e=>e.id===activeElement&&e.wall===w):null;
let dim='';if(chosen&&activeField){const e=chosen,k=activeField.key,x=ox+e.x*s,y=b-e.y*s;let p1,p2,label;if(k==='x'){p1=[ox,b+30];p2=[x,b+30];label=e.x+' mm'}if(k==='y'){p1=[ox+L*s+26,b];p2=[ox+L*s+26,y];label=e.y+' mm'}if(k==='w'){p1=[x,y-e.h*s-17];p2=[x+e.w*s,y-e.h*s-17];label=e.w+' mm'}if(k==='h'){p1=[x+e.w*s+16,y];p2=[x+e.w*s+16,y-e.h*s];label=e.h+' mm'}if(p1){dim=`<path d="M${p1} L${p2}" stroke="#cb7c28" stroke-width="2"/><circle cx="${p1[0]}" cy="${p1[1]}" r="3" fill="#cb7c28"/><circle cx="${p2[0]}" cy="${p2[1]}" r="3" fill="#cb7c28"/><text x="${(p1[0]+p2[0])/2+7}" y="${(p1[1]+p2[1])/2-7}" fill="#a45e19" font-size="13" font-weight="600">${label}</text>`}}
return `<svg viewBox="0 0 720 390" aria-label="Widok ściany ${'ABCD'[w]}" data-scale="${s}"><rect x="${ox}" y="${oy}" width="${L*s}" height="${r.h*s}" fill="#fff" stroke="#315674" stroke-width="2"/><path d="M${ox},${oy-15}v-12m0,6h${L*s}m0,-6v12" stroke="#9aacba"/><text x="360" y="${oy-29}" text-anchor="middle" fill="#365773" font-size="14">${L} mm</text><text x="${ox-18}" y="${oy+r.h*s/2}" text-anchor="middle" transform="rotate(-90 ${ox-18} ${oy+r.h*s/2})" fill="#365773" font-size="13">${r.h} mm</text>${r.elements.filter(e=>e.wall===w).map(e=>{const x=ox+e.x*s,y=b-e.y*s,on=e.id===activeElement,st=on?'#cc812e':'#477898';return `<g data-element="${e.id}" tabindex="0" role="button" aria-label="${types[e.type][0]}, X ${e.x}, Y ${e.y}. Przeciągnij lub użyj strzałek." onkeydown="nudgeElement(event,'${e.id}')" style="cursor:grab;touch-action:none">${isOpening(e)?`<rect x="${x}" y="${y-e.h*s}" width="${e.w*s}" height="${e.h*s}" fill="${e.type==='window'?'#d8edf1':'#e5edf2'}" stroke="${st}" stroke-width="${on?3:2}"/><path d="M${x} ${y-e.h*s}L${x+e.w*s} ${y}" stroke="${st}" opacity=".3"/><text x="${x+e.w*s/2}" y="${y-e.h*s/2}" text-anchor="middle" fill="#3a657e" font-size="12">${types[e.type][0]}</text>`:`<circle cx="${x}" cy="${y}" r="21" fill="transparent"/><circle cx="${x}" cy="${y}" r="11" fill="${e.type==='water'?'#b8dedd':'#e2edf4'}" stroke="${st}" stroke-width="${on?3:2}"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="13" fill="#315674">${types[e.type][1]}</text>`}<text x="${x}" y="${Math.min(375,y+24)}" font-size="11" fill="#59758a">${e.x} / ${e.y}</text></g>`}).join('')}<path d="M${ox-7} ${b+4}h${L*s+14}" stroke="#9cafbc" stroke-width="2"/>${dim}</svg>`;};
function bindWallDrag(){const svg=$('#wallCanvas svg');if(!svg)return;let drag=null;const p=ev=>new DOMPoint(ev.clientX,ev.clientY).matrixTransform(svg.getScreenCTM().inverse());svg.onpointerdown=ev=>{const g=ev.target.closest('[data-element]');if(!g)return;ev.preventDefault();const e=room().elements.find(e=>e.id===g.dataset.element);activeElement=e.id;activeField={id:e.id,key:'x'};drag={e,g,start:p(ev),x:e.x,y:e.y};svg.setPointerCapture(ev.pointerId);document.querySelectorAll('[data-row]').forEach(row=>row.classList.toggle('selected',row.dataset.row===e.id));};svg.onpointermove=ev=>{if(!drag)return;ev.preventDefault();const pt=p(ev),s=+svg.dataset.scale,e=drag.e,r=room();e.x=clamp(Math.round(drag.x+(pt.x-drag.start.x)/s),0,length(r,wall)-(isOpening(e)?e.w:0));e.y=clamp(Math.round(drag.y-(pt.y-drag.start.y)/s),0,r.h-(isOpening(e)?e.h:0));drag.g.setAttribute('transform',`translate(${(e.x-drag.x)*s},${-(e.y-drag.y)*s})`);for(const k of ['x','y']){const input=$(`#cell-${e.id}-${k}`);if(input)input.value=e[k]}$('#dragReadout').textContent=`X ${e.x} · Y ${e.y} mm`;update3D();};const finish=ev=>{if(!drag)return;if(ev.type==='pointercancel'){drag.e.x=drag.x;drag.e.y=drag.y}drag=null;save();refreshGeometry();for(const k of ['x','y']){const e=room().elements.find(e=>e.id===activeElement),input=$(`#cell-${e.id}-${k}`);if(input)input.value=e[k]}};svg.onpointerup=finish;svg.onpointercancel=finish;}
function nudgeElement(ev,id){const step=ev.shiftKey?10:1,dirs={ArrowLeft:[-step,0],ArrowRight:[step,0],ArrowUp:[0,step],ArrowDown:[0,-step]};if(!dirs[ev.key])return;ev.preventDefault();const e=room().elements.find(e=>e.id===id),r=room(),[dx,dy]=dirs[ev.key];e.x=clamp(e.x+dx,0,length(r,wall)-(isOpening(e)?e.w:0));e.y=clamp(e.y+dy,0,r.h-(isOpening(e)?e.h:0));activeElement=id;activeField={id,key:dx?'x':'y'};save();refreshGeometry();for(const k of ['x','y'])$(`#cell-${id}-${k}`).value=e[k];$(`[data-element="${id}"]`)?.focus({preventScroll:true})}
let photoOwner=null,photoFieldId=null;function openInlinePhoto(field,id){photoOwner=id?room().elements.find(e=>e.id===id):room();photoFieldId=field;photoValue=photoOwner.photo||'';ocrTarget=field;$('#inlinePhoto').hidden=false;$('#photoHeading').textContent='Zdjęcie pomiaru · '+$('#'+field).getAttribute('aria-label');$('#photoPreview').hidden=!photoValue;$('#photoPreview').src=photoValue;$('#ocrPanel').innerHTML='';$('#photoInput').value='';$('#photoInput').onchange=async ev=>{const owner=photoOwner;await readPhoto(ev);owner.photo=photoValue;save()};$('#inlinePhoto').scrollIntoView({behavior:'smooth',block:'nearest'});$('#photoInput').click();}
acceptOCR=function(){const n=+$('#ocrNumber').value,u=+$('#ocrUnit').value;if(!u||!Number.isFinite(n)||!$('#ocrNumber').value){toast('Podaj wartość i jednostkę z dalmierza.');return}const input=$('#'+ocrTarget);if(!input){toast('Wybierz ponownie komórkę pomiaru.');return}input.value=Math.round(n*u);input.dispatchEvent(new Event('input',{bubbles:true}));toast(input.classList.contains('invalid')?'Odczyt nie mieści się w ścianie. Popraw wartość.':'Odczyt zapisano w komórce.');};
// A geometrical 3D projection: one coordinate system shared with the floor plan.
// A runs left→right, B top→bottom, C right→left, D bottom→top, viewed from inside.
function wallPoint(r,w,u,z){return w===0?[r.x+u,r.y,z]:w===1?[r.x+r.w,r.y+u,z]:w===2?[r.x+r.w-u,r.y+r.d,z]:[r.x,r.y+r.d-u,z]}
function sceneSVG(scope='room',yaw=sceneYaw,tilt=sceneTilt){const rooms=scope==='all'?data.rooms:[room()],co=Math.cos(yaw),si=Math.sin(yaw),ct=Math.cos(tilt),st=Math.sin(tilt);const project=([x,y,z])=>{const a=x*co-y*si,b=x*si+y*co;return [a,b*st-z*ct,b*ct+z*st]};const shapes=[];function poly(points,fill,stroke,opacity=1,extra=''){const pp=points.map(project);shapes.push({depth:pp.reduce((s,p)=>s+p[2],0)/pp.length,points:pp,markup:`<polygon points="${pp.map(p=>p.slice(0,2).join(',')).join(' ')}" fill="${fill}" stroke="${stroke}" stroke-width="12" opacity="${opacity}" ${extra}/>`})}const labels=[];
for(const r of rooms){poly([[r.x,r.y,0],[r.x+r.w,r.y,0],[r.x+r.w,r.y+r.d,0],[r.x,r.y+r.d,0]],r.id===roomId?'#d6e2e8':'#e7edf1','#9bb1c0');const normals=[[0,-1],[1,0],[0,1],[-1,0]];for(let w=0;w<4;w++){const L=length(r,w),els=r.elements.filter(e=>e.wall===w),holes=els.filter(e=>['door','window'].includes(e.type));const near=normals[w][0]*si+normals[w][1]*co>0;const alpha=sceneCutaway&&near?.12:.78;const xs=[...new Set([0,L,...holes.flatMap(e=>[clamp(e.x,0,L),clamp(e.x+e.w,0,L)])])].sort((a,b)=>a-b),zs=[...new Set([0,r.h,...holes.flatMap(e=>[clamp(e.y,0,r.h),clamp(e.y+e.h,0,r.h)])])].sort((a,b)=>a-b);for(let i=0;i<xs.length-1;i++)for(let j=0;j<zs.length-1;j++){const x=(xs[i]+xs[i+1])/2,z=(zs[j]+zs[j+1])/2;if(holes.some(e=>x>e.x&&x<e.x+e.w&&z>e.y&&z<e.y+e.h))continue;poly([wallPoint(r,w,xs[i],zs[j]),wallPoint(r,w,xs[i+1],zs[j]),wallPoint(r,w,xs[i+1],zs[j+1]),wallPoint(r,w,xs[i],zs[j+1])],r.id===roomId&&w===wall?'#b6d1df':'#dce6ed','#7795aa',alpha)}const lab=project(wallPoint(r,w,L/2,r.h+160));labels.push(`<text x="${lab[0]}" y="${lab[1]}" font-size="170" text-anchor="middle" fill="#476b84">${'ABCD'[w]}</text>`);for(const e of els){if(isOpening(e)){poly([wallPoint(r,w,e.x,e.y),wallPoint(r,w,e.x+e.w,e.y),wallPoint(r,w,e.x+e.w,e.y+e.h),wallPoint(r,w,e.x,e.y+e.h)],e.type==='window'?'#97cfdd':e.type==='door'?'#b5b3a7':'#9aaebe',e.id===activeElement?'#ce832e':'#497491',e.type==='door'?.2:.65)}else{const radius=75,points=Array.from({length:16},(_,i)=>wallPoint(r,w,e.x+radius*Math.cos(i*Math.PI/8),e.y+radius*Math.sin(i*Math.PI/8)));poly(points,e.type==='water'?'#209caa':e.type==='drain'?'#607583':'#f4b859',e.id===activeElement?'#d1761e':'#365e79',1)}}}const name=project([r.x+r.w/2,r.y+r.d/2,0]);labels.push(`<text x="${name[0]}" y="${name[1]}" font-size="170" text-anchor="middle" fill="#36556d">${esc(r.name)}</text>`)}const all=shapes.flatMap(s=>s.points),minX=Math.min(...all.map(p=>p[0]))-400,maxX=Math.max(...all.map(p=>p[0]))+400,minY=Math.min(...all.map(p=>p[1]))-450,maxY=Math.max(...all.map(p=>p[1]))+300;shapes.sort((a,b)=>a.depth-b.depth);return `<svg viewBox="${minX} ${minY} ${maxX-minX} ${maxY-minY}" aria-label="Model 3D: ${scope==='all'?'cały lokal':esc(room().name)}">${shapes.map(s=>s.markup).join('')}${labels.join('')}</svg>`}
function update3D(){if($('#mini3D'))$('#mini3D').innerHTML=sceneSVG('room');if($('#sceneLarge'))$('#sceneLarge').innerHTML=sceneSVG(sceneScope);if($('#planMini3D'))$('#planMini3D').innerHTML=sceneSVG('all');}
function open3D(scope=view==='plan'?'all':'room'){sceneScope=scope;$('#dialog').classList.add('scene-dialog');modal(`<div class="scene-heading"><div><div class="eyebrow">MODEL Z AKTUALNYCH POMIARÓW</div><h2>Podgląd przestrzenny</h2></div><button onclick="closeDialog()">Zamknij</button></div><div class="scene-controls"><select aria-label="Zakres modelu 3D" onchange="sceneScope=this.value;update3D()"><option value="room" ${scope==='room'?'selected':''}>Wybrany pokój</option><option value="all" ${scope==='all'?'selected':''}>Cały lokal</option></select><label><input type="checkbox" ${sceneCutaway?'checked':''} onchange="sceneCutaway=this.checked;update3D()"> Odsłoń wnętrze</label></div><div id="sceneLarge"></div><div class="scene-sliders"><label>Obrót <input aria-label="Obrót modelu 3D" type="range" min="-180" max="180" value="${Math.round(sceneYaw*180/Math.PI)}" oninput="sceneYaw=+this.value*Math.PI/180;update3D()"></label><label>Nachylenie <input aria-label="Nachylenie modelu 3D" type="range" min="15" max="80" value="${Math.round(sceneTilt*180/Math.PI)}" oninput="sceneTilt=+this.value*Math.PI/180;update3D()"></label></div><p class="muted">Turkus: woda · złoty: elektryka · szary: odpływ. Położenia są zgodne z pomiarami; symbole instalacji powiększono dla czytelności. Podgląd poglądowy, bez grubości ścian.</p>`);update3D()}
$('#dialog').addEventListener('close',()=>$('#dialog').classList.remove('scene-dialog'));
const previousPlan=renderPlan;renderPlan=function(){previousPlan();const card=document.createElement('div');card.className='card plan-model';card.innerHTML='<div class="card-top"><h3>Cały lokal · 3D</h3><button onclick="open3D(\'all\')">⤢ Powiększ</button></div><button class="model-mini" id="planMini3D" onclick="open3D(\'all\')" aria-label="Powiększ model całego lokalu"></button>';$('#content').append(card);update3D()};
